// Grid layout positions for 12 logos in a 4x3 grid
const GRID_COLS = 4;
const GRID_ROWS = 3;

const LogoCard: React.FC<{
  company: (typeof AI_COMPANIES)[number];
  index: number;
  delay: number;
}> = ({ company, index, delay }) => {
  const frame = useCurrentFrame();
  const { fps: videoFps } = useVideoConfig();

  const progress = spring({
    frame,
    fps: videoFps,
    delay,
    config: { damping: 180, stiffness: 100, mass: 0.8 },
  });

  const scaleVal = interpolate(progress, [0, 1], [0.3, 1]);
  const opacityVal = interpolate(progress, [0, 0.6], [0, 1]);
  const yOffset = interpolate(progress, [0, 1], [80, 0]);

  const LogoComp = LOGO_COMPONENTS[company.symbol];

  // Floating animation
  const floatOffset = Math.sin((frame + index * 8) / 18) * 12;

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 32,
        transform: `scale(${scaleVal}) translateY(${yOffset + floatOffset * progress}px)`,
        opacity: opacityVal,
      }}
    >
      {/* Logo container */}
      <div
        style={{
          width: 200,
          height: 200,
          borderRadius: 48,
          backgroundColor: company.color === "#FFFFFF"
            ? "rgba(255,255,255,0.12)"
            : `${company.color}22`,
          border: `3px solid ${company.color}44`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          boxShadow: `0 0 60px ${company.color}33, 0 20px 60px rgba(0,0,0,0.4)`,
          backdropFilter: "blur(10px)",
        }}
      >
        <LogoComp size={100} />
      </div>

      {/* Name */}
      <div
        style={{
          fontSize: 30,
          fontWeight: 700,
          color: "rgba(255,255,255,0.85)",
          letterSpacing: "0.02em",
          fontFamily: "'Inter', sans-serif",
          textAlign: "center",
          textShadow: "0 2px 20px rgba(0,0,0,0.6)",
          lineHeight: 1.2,
        }}
      >
        {company.name}
      </div>
    </div>
  );
};

